func registerToolLoopTranslations() {
	for lang, localized := range toolLoopStrings() {
		AddTranslation(lang, MsgToolLoopAbortRepeatedOverwrite, localized.AbortRepeatedOverwrite)
		AddTranslation(lang, MsgToolLoopAbortIdenticalRepeat, localized.AbortIdenticalRepeat)
		AddTranslation(lang, MsgToolLoopAbortErrorRepeat, localized.AbortErrorRepeat)
		AddTranslation(lang, MsgToolLoopAbortPingPong, localized.AbortPingPong)
		AddTranslation(lang, MsgToolLoopAbortPollingNoProgress, localized.AbortPollingNoProgress)
		AddTranslation(lang, MsgToolLoopAbortGeneric, localized.AbortGeneric)
		AddTranslation(lang, MsgToolLoopRecoveryRepeatedOverwrite, localized.RecoveryRepeatedOverwrite)
		AddTranslation(lang, MsgToolLoopRecoveryGeneric, localized.RecoveryGeneric)
	}
}
